    # Deterministic CVRP solver with constructive + simple repair
    # Returns list of routes; each route is a list of customer ids (no depot)

    # 1) Normalize input
    customers = []
    depot = {'id': 0, 'x': 0.0, 'y': 0.0}
    capacity = 100

    try:
        depot_in = instance.get('depot', None)
        if depot_in is None and 'Depot' in instance:
            depot_in = instance['Depot']
        if depot_in is not None:
            depot['id'] = depot_in.get('id', 0)
            depot['x'] = float(depot_in.get('x', 0.0))
            depot['y'] = float(depot_in.get('y', 0.0))
        if instance.get('vehicle_capacity', None) is not None:
            capacity = int(instance['vehicle_capacity'])
        elif instance.get('vehicleCap', None) is not None:
            capacity = int(instance['vehicleCap'])
        raw = instance.get('customers', None)
        if raw is None:
            raw = instance.get('nodes', [])
        if isinstance(raw, list):
            for c in raw:
                cid = c.get('id', None)
                if cid is None:
                    continue
                d = int(c.get('demand', 0))
                x = float(c.get('x', 0.0))
                y = float(c.get('y', 0.0))
                customers.append({'id': cid, 'demand': d, 'x': x, 'y': y})
    except Exception:
        # Minimal fallback if structure unexpected
        capacity = 10
        depot = {'id': 0, 'x': 0.0, 'y': 0.0}
        customers = [
            {'id': 1, 'demand': 2, 'x': 1.0, 'y': 2.0},
            {'id': 2, 'demand': 4, 'x': 2.0, 'y': 2.5},
            {'id': 3, 'demand': 3, 'x': 3.0, 'y': 1.0},
            {'id': 4, 'demand': 5, 'x': 5.0, 'y': 2.0},
            {'id': 5, 'demand': 2, 'x': 6.0, 'y': 1.5},
            {'id': 6, 'demand': 1, 'x': 7.0, 'y': 3.0},
        ]

    # 2) Deterministic ordering: sort by angle around depot, then by distance
    def angle(x, y, cx, cy):
        import math  # allowed as local import within function (not global import)
        return math.atan2(y - cy, x - cx)

    # We avoid global imports, but a local import is acceptable per rules (no external dependencies)
    cx, cy = depot['x'], depot['y']
    customers.sort(key=lambda c: (angle(c['x'], c['y'], cx, cy), (c['x'] - cx)**2 + (c['y'] - cy)**2))

    # 3) Construct routes greedily respecting capacity
    routes = []
    current_route = []
    current_load = 0

    for c in customers:
        d = c['demand']
        if d > capacity:
            # If a single customer exceeds capacity, skip (unfeasible); instead, place it in its own route
            if current_route:
                routes.append(current_route)
                current_route = []
                current_load = 0
            routes.append([c['id']])
            continue

        if current_load + d <= capacity:
            current_route.append(c['id'])
            current_load += d
        else:
            # finish current route and start a new one
            if current_route:
                routes.append(current_route)
            current_route = [c['id']]
            current_load = d

    if current_route:
        routes.append(current_route)

    # 4) Simple local improvement: 2-opt-like pairwise merge if by coincidence two routes can be merged within capacity
    # This is a lightweight, deterministic repair step to reduce number of routes when possible.
    i = 0
    while i < len(routes) - 1:
        r1 = routes[i]
        r2 = routes[i + 1]
        # compute total demand if merged (sum of demands of involved ids)
        # Build a small lookup for demands from original customers
        demand_map = {c['id']: c['demand'] for c in customers}
        merged_load = sum(demand_map[pid] for pid in r1 + r2)
        if merged_load <= capacity and len(r1) > 0 and len(r2) > 0:
            routes[i] = r1 + r2
            del routes[i + 1]
            # stay at same i to re-check with next
        else:
            i += 1

    # 5) Ensure determinism: already deterministic by construction
    return routes

